protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF9: default discriminator property renamed from "Discriminator" to "$type".
        // Existing 500K documents use "Discriminator" — preserve for compatibility.
        entity.HasDiscriminator<string>("Discriminator");

        // EF9: id no longer includes the discriminator (was "Product|123", now "123").
        // Existing documents use the old compound format — preserve for compatibility.
        entity.HasRootDiscriminatorInJsonId(true);
    });
    // Removed HasIndex — EF9 Cosmos provider now throws on HasIndex calls.
    // Manage indexing via the container's indexing policy in Azure Portal/Bicep/Terraform.
}

